WITH lines AS (SELECT id, effective_from, currency, EXPLODE(discounts) AS element FROM price_tiers) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, CASE WHEN element >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, ROUND(AVG(element), 2) AS avg_element, SUM(CASE WHEN currency = 'USD' THEN element ELSE 0 END) AS usd_element, ROUND(AVG(element), 2) AS avg_element_2, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows, GROUPING_ID() AS gid FROM lines GROUP BY CUBE (DATE_TRUNC('YEAR', effective_from), CASE WHEN element >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING SUM(CASE WHEN currency = 'USD' THEN element ELSE 0 END) > 0 ORDER BY avg_element NULLS FIRST;
